args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?spouse ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Anne_Elizabeth_Rector (dbo:spouse|dbp:spouse) ?spouse .
  OPTIONAL { ?spouse dbo:birthPlace ?birthPlace . }
  OPTIONAL { ?spouse dbp:birthPlace ?birthPlace . }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER(lang(?birthPlaceLabel) = "en") }
}

